local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_GREET, 'Oh hello, nice to see you |PLAYERNAME|.')
npcHandler:setMessage(MESSAGE_FAREWELL, 'See you later.')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'See you later.')
keywordHandler:addKeyword({'willie'}, StdModule.say, {npcHandler = npcHandler, text = 'He\'s funny in his own, gruffy way.'})
keywordHandler:addKeyword({'castle'}, StdModule.say, {npcHandler = npcHandler, text = 'If you travel to Thais, you really should visit the marvelous castle.'})
keywordHandler:addKeyword({'weapon'}, StdModule.say, {npcHandler = npcHandler, text = 'The best weapons on this isle are just toothpicks, compared with the weapons warriors of the mainland wield.'})
keywordHandler:addKeyword({'dallheim'}, StdModule.say, {npcHandler = npcHandler, text = 'An extraordinary warrior. He\'s the first and last line of defense of Rookgaard.'})
keywordHandler:addKeyword({'monster'}, StdModule.say, {npcHandler = npcHandler, text = 'Oh, I fought orcs, cyclopses, minotaurs, and even green dragons.'})
keywordHandler:addKeyword({'sea'}, StdModule.say, {npcHandler = npcHandler, text = 'My trip over the sea was horrible. The weather was bad, the waves high and my raft quite simple.'})
keywordHandler:addKeyword({'cyclops'}, StdModule.say, {npcHandler = npcHandler, text = 'Horrible monsters they are.'})
keywordHandler:addKeyword({'assistant'}, StdModule.say, {npcHandler = npcHandler, text = 'I have a job of great responsibility. Mostly I keep annoying persons away from my boss.'})
keywordHandler:addKeyword({'explore'}, StdModule.say, {npcHandler = npcHandler, text = 'I have been almost everywhere in Tibia.'})
keywordHandler:addKeyword({'help'}, StdModule.say, {npcHandler = npcHandler, text = 'I can\'t help you much beyond information.'})
keywordHandler:addKeyword({'king'}, StdModule.say, {npcHandler = npcHandler, text = 'King Tibianus is the ruler of Thais.'})
keywordHandler:addKeyword({'raft'}, StdModule.say, {npcHandler = npcHandler, text = 'I left my raft at the south eastern shore. I forgot my private notebook on it. If you could return it to me I would be very grateful.'})
keywordHandler:addKeyword({'dungeon'}, StdModule.say, {npcHandler = npcHandler, text = 'I have not had the time to explore the dungeons of this isle, but I have seen two big caves in the east, and there is a ruined tower in the northwest.'})
keywordHandler:addKeyword({'thais'}, StdModule.say, {npcHandler = npcHandler, text = 'A fine city, but the king has some problems enforcing the law.'})
keywordHandler:addKeyword({'seymour'}, StdModule.say, {npcHandler = npcHandler, text = 'I think this poor guy was a bad choice as the head of the academy.'})
keywordHandler:addKeyword({'tibia'}, StdModule.say, {npcHandler = npcHandler, text = 'I try to explore each spot of Tibia, and one day I will succeed.'})
keywordHandler:addKeyword({'cipfried'}, StdModule.say, {npcHandler = npcHandler, text = 'A gentle person. You should visit him, if you have problems.'})
keywordHandler:addKeyword({'sewer'}, StdModule.say, {npcHandler = npcHandler, text = 'I like sewers. I made my very first battle experience in the Thais sewers. The small sewersystem of Rookgaard has some nasty rats to fight.'})
keywordHandler:addKeyword({'food'}, StdModule.say, {npcHandler = npcHandler, text = 'My favorite dish is salmon. Oh please, bring me some of it.'})
keywordHandler:addKeyword({'time'}, StdModule.say, {npcHandler = npcHandler, text = 'Sorry, I lost my watch in a storm.'})
keywordHandler:addKeyword({'adventure'}, StdModule.say, {npcHandler = npcHandler, text = 'I fought fierce monsters, climbed the highest mountains, and crossed the sea on a raft.'})
keywordHandler:addKeyword({'magic'}, StdModule.say, {npcHandler = npcHandler, text = 'You can learn spells only in the guildhalls of the mainland.'})
keywordHandler:addKeyword({'orcish'}, StdModule.say, {npcHandler = npcHandler, text = 'I speak some orcish words, not much though, just \'yes\' and \'no\' and such basic.'})
keywordHandler:addKeyword({'orc'}, StdModule.say, {npcHandler = npcHandler, text = 'Not the nicest guys you can encounter. I had some clashes with them and was prisoner of the orcs for some months.'})
keywordHandler:addKeyword({'obi'}, StdModule.say, {npcHandler = npcHandler, text = 'He\'s a funny little man.'})
keywordHandler:addKeyword({'academy'}, StdModule.say, {npcHandler = npcHandler, text = 'A fine institution, but it needs definitely more funds from the king.'})
keywordHandler:addKeyword({'hyacinth'}, StdModule.say, {npcHandler = npcHandler, text = 'Hyacinth is a great healer. He lives somewhere hidden on this isle.'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I explore and seek adventure.'})
keywordHandler:addKeyword({'information'}, StdModule.say, {npcHandler = npcHandler, text = 'Just ask and I\'ll try to answer.'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)

local focusModule = FocusModule:new()
focusModule:addGreetMessage('hi')
focusModule:addGreetMessage('hello')
npcHandler:addModule(focusModule)

